import { ElDialog, ElForm, ElFormItem, ElInput, ElSelect, ElOption, ElButton } from 'element-plus';
import { networkList } from '@/utils/network.js';
import { ref } from 'vue';
import axios from 'axios';

// 弹出框显示状态

export default {
  __name: 'AddContainerDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);

    // 打开弹出框
    const openDialog = () => {
      dialogVisible.value = true;
    };

    // 容器数据
    const container = ref({
      image: '',
      name: '',
      networks: []
    });

    // 提交容器数据
    const submitAdd = async () => {
      try {
        console.log('Container created successfully');
        await axios.post('http://localhost:8081/container/create', container.value);
        dialogVisible.value = false;
      } catch (error) {
        console.error('Error creating container:', error.response || error);
        alert('Error: ' + (error.response ? error.response.data : error.message));
      }
    };
    __expose({
      openDialog
    });
    const __returned__ = {
      dialogVisible,
      openDialog,
      container,
      submitAdd,
      get ElDialog() {
        return ElDialog;
      },
      get ElForm() {
        return ElForm;
      },
      get ElFormItem() {
        return ElFormItem;
      },
      get ElInput() {
        return ElInput;
      },
      get ElSelect() {
        return ElSelect;
      },
      get ElOption() {
        return ElOption;
      },
      get ElButton() {
        return ElButton;
      },
      get networkList() {
        return networkList;
      },
      ref,
      get axios() {
        return axios;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
